mapper.select:
SELECT sod.id, sod.main_id, sod.sku_id, sod.sku_no, sod.plan_qty, sod.actual_qty, sod.warehouse_location, sod.is_close, sod.remark, sod.source_detail_id, so.approve_status, so.invalid_status FROM so_outstock_detail sod INNER JOIN so_outstock so ON sod.main_id = so.id AND sod.is_deleted = FALSE WHERE so.is_deleted = FALSE AND so.invalid_status = FALSE
AND sod.source_detail_id in
#{id}

SELECT sod.id, sod.main_id, sod.sku_id, sod.sku_no, sod.plan_qty, sod.actual_qty, sod.warehouse_location, sod.is_close, sod.remark, sod.source_detail_id, sod.so_detail_id, so.approve_status, so.invalid_status, so.so_id FROM so_outstock so INNER JOIN so_outstock_detail sod ON sod.main_id = so.id AND so.is_deleted=FALSE WHERE sod.is_deleted = FALSE AND so.invalid_status = FALSE
AND so.so_id IN
#{id}

select sod.id, sod.main_id, sod.sku_id, sod.sku_no, sod.plan_qty, sod.actual_qty, sod.warehouse_location, sod.is_close, sod.remark, sod.source_detail_id, so.approve_status, sod.so_detail_id, so.so_id from so_outstock so inner join so_outstock_detail sod on sod.main_id = so.id and sod.is_deleted=FALSE where so.is_deleted = false and so.invalid_status = false
and sod.so_detail_id in
#{id}

SELECT so.id, sod.sku_id, sod.sku_no, SUM(sod.actual_qty) AS deliveryQty FROM so_outstock so INNER JOIN so_outstock_detail sod ON so.id = sod.main_id AND sod.is_deleted = FALSE WHERE so.is_deleted = FALSE
AND sod.main_id = #{mainId}
GROUP BY so.id, sod.sku_id, sod.sku_no

SELECT sod.sku_id AS skuId, MAX(so.bill_date) AS billDate FROM so_outstock_detail sod INNER JOIN so_outstock so ON sod.main_id = so.id AND sod.is_deleted = FALSE WHERE so.approve_status = 'approve' AND sod.sku_id IN
#{skuId}
and so.is_deleted = FALSE and sod.is_deleted = FALSE GROUP BY sod.sku_id
